486→/* =============================================================================
487→   SPINNER - SpinKit Grid (3x3)
488→
489→   A simple grid-based loading spinner that inherits size from font-size
490→   and color from currentColor.
491→
492→   Usage:
493→     <div class="spinner">
494→       <div class="spinner-cube"></div>
495→       <div class="spinner-cube"></div>
496→       ...9 cubes total
497→     </div>
498→============================================================================= */
499→
500→.spinner {
501→  display: inline-grid;
502→  grid-template-columns: repeat(3, 1fr);
503→  width: 1em;
504→  height: 1em;
505→  gap: 0.08em;
506→}
507→
508→.spinner-cube {
509→  background-color: currentColor;
510→  animation: spinner-grid 1.3s infinite ease-in-out;
511→  transform: scale3d(0.5, 0.5, 1);
512→}
513→
514→.spinner-cube:nth-child(1) { animation-delay: 0.2s; }
515→.spinner-cube:nth-child(2) { animation-delay: 0.3s; }
516→.spinner-cube:nth-child(3) { animation-delay: 0.4s; }
517→.spinner-cube:nth-child(4) { animation-delay: 0.1s; }
518→.spinner-cube:nth-child(5) { animation-delay: 0.2s; }
519→.spinner-cube:nth-child(6) { animation-delay: 0.3s; }
520→.spinner-cube:nth-child(7) { animation-delay: 0s; }
521→.spinner-cube:nth-child(8) { animation-delay: 0.1s; }
522→.spinner-cube:nth-child(9) { animation-delay: 0.2s; }
523→
524→@keyframes spinner-grid {
525→  0%, 70%, 100% {
526→    transform: scale3d(0.5, 0.5, 1);
527→  }
528→  35% {
529→    transform: scale3d(0, 0, 1);
530→  }
531→}
532→
533→/* =============================================================================
534→   SHIMMER ANIMATION
535→
536→   Subtle shimmer effect for optimistic UI states.
537→============================================================================= */
538→
539→@keyframes shimmer {
540→  0% {
541→    background-position: -200% 0;
542→  }
543→  100% {
544→    background-position: 200% 0;
545→  }
546→}
547→
548→.animate-shimmer {
549→  position: relative;
550→  overflow: hidden;
551→}
552→
553→.animate-shimmer::after {
554→  content: '';
555→  position: absolute;
556→  inset: 0;
557→  background: linear-gradient(
558→    90deg,
559→    transparent 0%,
560→    oklch(from var(--foreground) l c h / 0.06) 50%,
561→    transparent 100%
562→  );
563→  background-size: 200% 100%;
564→  animation: shimmer 1.5s ease-in-out infinite;
565→  pointer-events: none;
566→  border-radius: inherit;
567→}
