 1→import { motion } from 'motion/react'
 2→import { OrchaAgentsSymbol } from './icons/OrchaAgentsSymbol'
 3→
 4→interface SplashScreenProps {
 5→  isExiting: boolean
 6→  onExitComplete?: () => void
 7→}
 8→
 9→/**
10→ * SplashScreen - Shows Craft symbol during app initialization
11→ *
12→ * Displays centered symbol on app background, fades out when app is fully ready.
13→ * On exit, the symbol scales up and fades out quickly while the background fades slower.
14→ */
15→export function SplashScreen({ isExiting, onExitComplete }: SplashScreenProps) {
16→  return (
17→    <motion.div
18→      className={`fixed inset-0 z-splash flex items-center justify-center bg-background ${isExiting ? 'pointer-events-none' : ''}`}
19→      initial={{ opacity: 1 }}
20→      animate={{ opacity: isExiting ? 0 : 1 }}
21→      transition={{ duration: 0.5, ease: 'easeOut' }}
22→      onAnimationComplete={() => {
23→        if (isExiting && onExitComplete) {
24→          onExitComplete()
25→        }
26→      }}
27→    >
28→      <motion.div
29→        initial={{ scale: 1.5, opacity: 1 }}
30→        animate={{
31→          scale: isExiting ? 3 : 1.5,
32→          opacity: isExiting ? 0 : 1
33→        }}
34→        transition={{
35→          duration: 0.2,
36→          ease: [0.16, 1, 0.3, 1] // Exponential out curve
