 49→() => {
 50→  const toHex = (r, g, b) => '#' + [r, g, b].map(c => c.toString(16).padStart(2, '0')).join('');
 51→
 52→  const parseColor = (str) => {
 53→    if (!str) return null;
 54→    str = str.trim();
 55→    const hm = /^#([0-9a-f]{3,8})$/i.exec(str);
 56→    if (hm) {
 57→      const h = hm[1];
 58→      let r, g, b;
 59→      if (h.length === 3) { r = parseInt(h[0]+h[0],16); g = parseInt(h[1]+h[1],16); b = parseInt(h[2]+h[2],16); }
 60→      else if (h.length >= 6) { r = parseInt(h.slice(0,2),16); g = parseInt(h.slice(2,4),16); b = parseInt(h.slice(4,6),16); }
 61→      else return null;
 62→      return toHex(r, g, b);
 63→    }
 64→    const rm = str.match(/rgba?[\(]\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/);
 65→    if (rm) return toHex(+rm[1], +rm[2], +rm[3]);
 66→    return null;
 67→  };
 68→
 69→  const parseBg = (el) => {
 70→    if (!el) return null;
 71→    const bg = getComputedStyle(el).backgroundColor;
 72→    if (!bg || bg === 'transparent' || bg === 'rgba(0, 0, 0, 0)') return null;
 73→    return parseColor(bg);
 74→  };
 75→
 76→  // 1. theme-color meta — respect media attribute for light/dark
 77→  const metas = document.querySelectorAll('meta[name="theme-color"]');
 78→  for (const m of metas) {
 79→    const media = m.getAttribute('media');
 80→    if (media && !window.matchMedia(media).matches) continue;
 81→    const c = parseColor(m.content);
 82→    if (c) return c;
 83→  }
 84→
 85→  // 2. Safari-like approach: sample fixed/sticky elements at viewport top-center
 86→  const els = document.elementsFromPoint(window.innerWidth / 2, 4);
 87→  for (const el of els) {
 88→    if (el === document.documentElement || el === document.body) continue;
 89→    const style = getComputedStyle(el);
 90→    const pos = style.position;
 91→    if (pos !== 'fixed' && pos !== 'sticky') continue;
 92→    const rect = el.getBoundingClientRect();
 93→    if (rect.width < window.innerWidth * 0.8) continue;
 94→    const c = parseBg(el);
 95→    if (c) return c;
 96→  }
 97→
 98→  // 3. Fallback: body then html
 99→  return parseBg(document.body) || parseBg(document.documentElement) || null;
